Yes, the reason is quite important from application developer perspective.
Look at the following pseudo code:

`my_header.h`
```
/* Callback to the application */
struct my_callbacks {
   void (*value_cb)(struct my_inst* inst, int err, void *value);
};

/* Read the value */
int read_value(struct my_inst* inst);
```
`my_source.c`
```
/* Value notification callback */
void on_notification(struct my_inst* inst, void *value)
{
    cbs->value_cb(inst, 0, value);
}

void on_read_response(struct my_inst* inst, int err, void *value)
{
    cbs->value_cb(inst, 0, value);
}

int read_value(struct my_inst* inst)
{
   if (busy) {
         return -EBUSY;
   }
}
```
`my_app.c`
```
static k_sem value_read;
void value_cb()
{
  /* No one knows if it's the notification callback or read response callback */
  k_sem_give(value_read);
}

int main()
{
     int err;

     err = read_value(inst);
     /* err is 0 */
     k_sem_take(value_read);
       err = read_value(inst);
      /* err is -EBUSY because the callback was called on notification, not read response */  
}
```

I've seen such issue e.g. in `struct bt_micp_mic_ctlr_cb.mute`

Thus I added the separate callback parameter so that the caller knows when the operation is complete an it can start another one.
